    if (ee) { const h = holList(y).find(x => x.date === ee.dataset.holed); S.holEdit = h; renderHolidays(); const fo = $('#holf'); if (fo) fo.scrollIntoView({ block: 'center' }); return; }
    if (rs) { delete holidays[rs.dataset.holres]; try { await done({ holidays }); toast('Fecha restaurada'); await reviewConflicts([rs.dataset.holres]); } catch (er) {} return; }
