    const me = S.users[S.me] || {};
    const data = { title, text: f.text.value.trim(), aud: audOut, from, to, pin: f.pin.checked, by: n ? n.by : S.me, byName: n ? n.byName : me.name || '', role: n ? n.role : me.role || '', created: n ? n.created : Date.now(), updated: Date.now() };
    try { await Store.setNews(id || 'n' + uid(), data); closeModal(); toast(n ? 'Noticia actualizada' : 'Noticia publicada'); }
