  return `<div class="chips" id="hpros" style="margin-bottom:12px">${pros.map(([id, u]) => `<button type="button" class="pchoice" data-hpro="${esc(id)}" aria-pressed="${id === S.hpro}">${avatarHTML(u, 24)}${esc(u.name)}</button>`).join('')}</div>`;
