function renderReminders() {
  const box = $('#remsbox'); if (!box || !RM || RM.pro !== S.hpro) return;
  const sec = isSec(); const today = todayStr(); const by = RM.by;
  const items = []; Object.entries(by).forEach(([date, list]) => list.forEach(p => items.push({ date, p, h: +p._k.split('_')[1], m: p._k.split('_')[2] != null ? +p._k.split('_')[2] : 0 })));
  const act = x => (x.p.status || 'prog') === 'prog' || x.p.status === 'asist';
  const hoy = items.filter(x => x.date === today && act(x));
  const lim = fmt(addDays(nowBA(), 3));
  const ingresos = items.filter(x => x.p.n === 1 && !x.p.rec && (x.p.status || 'prog') === 'prog' && x.date <= lim).sort((a, b) => a.date.localeCompare(b.date) || a.h - b.h || a.m - b.m);
  const groups = {};
  items.forEach(x => { const p = x.p; if (!p.pid || !p.tid || (p.status || 'prog') !== 'prog') return; (groups[p.pid + '|' + p.tid] = groups[p.pid + '|' + p.tid] || { pid: p.pid, tid: p.tid, list: [] }).list.push(x); });
  const N = S.cfg.endReminder;
  const fins = Object.values(groups).map(g => {
    const pt = S.patients[g.pid]; const pl = pt && pt.plans && pt.plans[g.tid]; if (!pl || pl.status === 'finalizado') return null;
    g.list.sort((a, b) => a.date.localeCompare(b.date));
    return { name: pt.name, pl, rem: g.list.length, last: g.list[g.list.length - 1].date, unsched: Math.max(0, (pl.total || 0) - (pl.placed || 0)) };
  }).filter(x => x && x.rem <= N).sort((a, b) => a.last.localeCompare(b.last));
  const when = x => (x.date === today ? 'Hoy' : x.date === fmt(addDays(nowBA(), 1)) ? 'Mañana' : labelDate(x.date)) + ' ' + tm(x.h, x.m);
  const dxOf = p => { const pt = S.patients[p.pid]; const pl = pt && pt.plans && pt.plans[p.tid]; return (pl && pl.dx) || 'Sin diagnóstico cargado'; };
  const closed = isClosed(today);
  const title = sec ? 'Recordatorios de ' + esc((S.users[S.hpro] || {}).name || '') : 'Tus recordatorios';
  box.innerHTML = `<section class="panel" style="margin-bottom:14px"><div class="head-row"><h2 style="font-size:19px">${title}</h2><button class="btn ghost small" data-gotoag>Ver agenda</button></div>${remChips()}
      <div class="rem0"><b>${closed ? 'Hoy el centro está cerrado' : hoy.length ? `${hoy.length} ${hoy.length === 1 ? 'sesión' : 'sesiones'} hoy` : 'Sin sesiones hoy'}</b>${!closed && hoy.length ? `<small>${esc(tm(Math.min(...hoy.map(x => x.h)), 0))} a ${esc(tm(Math.max(...hoy.map(x => x.h)) + 1, 0))}</small>` : ''}</div></section>
    <section class="panel" style="margin-bottom:14px"><h2 style="font-size:17px;margin-bottom:6px">Ingresos</h2><p class="hint">Pacientes que empiezan hoy o en los próximos 3 días.</p>
      ${ingresos.length ? ingresos.map(x => `<div class="rem"><div><b>${esc(pname(x.p))}</b><small>${esc(when(x))}</small></div><p>${esc(dxOf(x.p))}${(S.patients[x.p.pid] || {}).insurance ? ' · ' + esc(S.patients[x.p.pid].insurance) : ''}</p></div>`).join('') : '<p class="hint" style="margin:0">No hay ingresos próximos.</p>'}</section>
    <section class="panel"><h2 style="font-size:17px;margin-bottom:6px">Finalización de tratamientos</h2><p class="hint">Tratamientos a los que les quedan ${N} sesiones programadas o menos.</p>
      ${fins.length ? fins.map(x => `<div class="rem"><div><b>${esc(x.name)}</b><small>${x.unsched ? 'Faltan agendar ' + x.unsched : 'Termina el ' + esc(labelDate(x.last))}</small></div><p>${esc(x.pl.dx || 'Sin diagnóstico cargado')}${planTypeText(x.pl) ? ' · ' + esc(planTypeText(x.pl)) : ''}. Le ${x.rem === 1 ? 'queda 1 sesión programada' : 'quedan ' + x.rem + ' sesiones programadas'} (${x.pl.placed || 0} de ${x.pl.total} agendadas${x.unsched ? '' : ', última el ' + esc(labelDate(x.last))}).</p></div>`).join('') : '<p class="hint" style="margin:0">No hay tratamientos por terminar.</p>'}</section>`;
  bindRemChips();
  const g = box.querySelector('[data-gotoag]'); if (g) g.onclick = () => { if (isSec()) S.proId = S.hpro; goTab('agenda'); };
}

/* ================= modo selección: borrar sesiones no realizadas ================= */
const delOk = st => st === 'prog' || st === 'cancel';
function toggleSelect() {
  if (S.sel) S.sel = null; else { S.recover = null; S.moving = null; S.sel = { proId: S.proId, items: {}, allPending: false }; renderRecoverBar(); }
  const b = $('#selmode'); if (b) b.textContent = S.sel ? 'Salir de selección' : 'Cancelar tratamiento';
  renderSelBar(); renderGrid();
}
function selCount() { return S.sel ? Object.keys(S.sel.items).length : 0; }
function renderSelBar() {
  const bar = $('#selbar'); if (!bar) return;
  if (!S.sel) { bar.innerHTML = ''; return; }
  const n = selCount();
  bar.innerHTML = `<div class="rbar selbar"><span><b>Cancelar tratamiento</b>: ${n} ${n === 1 ? 'sesión seleccionada' : 'sesiones seleccionadas'}. Tocá una sesión pendiente del paciente que no continúa y usá “Todas las pendientes del paciente”. Las realizadas y las faltas no se pueden seleccionar.</span>
    <div class="selact"><button class="btn ghost small" data-selpat ${n ? '' : 'disabled'}>Todas las pendientes del paciente</button><button class="btn danger small" data-seldel ${n ? '' : 'disabled'}>Borrar${n ? ' (' + n + ')' : ''}</button><button class="btn ghost small" data-selexit>Salir</button></div></div>`;
  bar.onclick = e => {
    if (e.target.closest('[data-selexit]')) toggleSelect();
    else if (e.target.closest('[data-selpat]')) selectPatientPending();
    else if (e.target.closest('[data-seldel]')) confirmDeleteSessions();
  };
}
function toggleSel(ln) {
  if (!S.sel) return;
  const date = ln.dataset.date, h = +ln.dataset.h, m = ln.dataset.m != null ? +ln.dataset.m : null, eid = ln.dataset.eid;
  const key = slotKey(date, h, m);
  const arr = ((S.agenda[mondayKey(date) + '_' + S.sel.proId] || {}).slots || {})[key] || [];
  const e = arr.find(p => p.id === eid); if (!e) return;
  if (!delOk(e.status || 'prog')) return toast('Solo se pueden borrar sesiones pendientes o canceladas. Las realizadas y las faltas quedan en el sistema para el control.');
  if (S.sel.items[eid]) delete S.sel.items[eid];
  else S.sel.items[eid] = { eid, date, key, pid: e.pid || '', tid: e.tid || '', name: pname(e), rec: !!e.rec };
  renderSelBar(); renderGrid();
}
async function selectPatientPending() {
  if (!S.sel || !selCount()) return toast('Primero tocá una sesión del paciente.');
  const keys = new Set(Object.values(S.sel.items).filter(x => x.pid && x.tid).map(x => x.pid + '|' + x.tid));
  if (!keys.size) return toast('Esa sesión no tiene un tratamiento asociado: seleccioná las demás una por una.');
  try {
    const by = await fetchEntries(S.sel.proId, todayStr(), fmt(addDays(nowBA(), 366))); let add = 0;
    Object.entries(by).forEach(([date, list]) => list.forEach(p => {
      if (!p.pid || !p.tid || !keys.has(p.pid + '|' + p.tid) || !delOk(p.status || 'prog') || S.sel.items[p.id]) return;
      S.sel.items[p.id] = { eid: p.id, date, key: p._k, pid: p.pid, tid: p.tid, name: pname(p), rec: !!p.rec }; add++;
    }));
    S.sel.allPending = true; renderSelBar(); renderGrid();
    toast(add ? `Se seleccionaron ${add} sesiones pendientes más, de hoy en adelante` : 'No hay más sesiones pendientes de ese paciente');
  } catch (e) { toast('No se pudieron buscar las sesiones.'); }
}
function confirmDeleteSessions() {
  if (!S.sel || !selCount() || !canEditAgenda(S.sel.proId)) return;
  const items = Object.values(S.sel.items); const n = items.length; const pats = new Set(items.map(x => x.pid || x.name)).size;
  $('#dialog').innerHTML = `<div class="scrim" style="z-index:80"><div class="sheet" role="alertdialog" aria-modal="true"><h2>Cancelar tratamiento</h2>
    <p class="sub">Se ${n === 1 ? 'borra 1 sesión pendiente o cancelada' : 'borran ' + n + ' sesiones pendientes o canceladas'} de ${pats} ${pats === 1 ? 'paciente' : 'pacientes'} y se libera su lugar. Las sesiones realizadas y las faltas quedan en el sistema para el control.</p>
    <label class="chk-line"><input type="checkbox" id="delfin" checked><span>Dar por finalizado el tratamiento (abandono) de ${pats === 1 ? 'este paciente' : 'estos pacientes'}</span></label>
    <div class="actions"><button class="btn danger" data-y>Borrar</button><button class="btn ghost" data-n>Volver</button></div></div></div>`;
  $('#dialog').onclick = async e => {
    if (e.target.closest('[data-n]') || e.target.matches('.scrim')) { $('#dialog').innerHTML = ''; return; }
    if (!e.target.closest('[data-y]')) return;
    const fin = $('#delfin').checked; $('#dialog').innerHTML = '';
    try { const r = await deleteSessions(S.sel.proId, items, fin); S.sel = null; renderSelBar(); const b = $('#selmode'); if (b) b.textContent = 'Cancelar tratamiento'; toast(`${r} ${r === 1 ? 'sesión borrada' : 'sesiones borradas'}${fin ? ' y tratamiento finalizado' : ''}`); renderGrid(); }
    catch (er) { console.error(er); toast('No se pudieron borrar todas las sesiones.'); }
  };
}
async function deleteSessions(proId, items, finalize) {
  if (!canEditAgenda(proId)) throw new Error('permiso');
  const byWeek = {}; items.forEach(it => { const wk = mondayKey(it.date); (byWeek[wk] = byWeek[wk] || []).push(it); });
  const dP = {}, dR = {}; const touched = new Set(); let n = 0;
  for (const [wk, list] of Object.entries(byWeek)) {
    const id = wk + '_' + proId; const doc = await Store.getAgenda(id); if (!doc || !doc.slots) continue; let ch = false;
    for (const it of list) {
      const arr = doc.slots[it.key]; if (!arr) continue; const i = arr.findIndex(p => p.id === it.eid); if (i < 0) continue;
      const ent = arr[i]; if (!delOk(ent.status || 'prog')) continue;          // nunca borra realizadas ni faltas
      arr.splice(i, 1); if (!arr.length) delete doc.slots[it.key]; ch = true; n++;
      if (ent.pid && ent.tid) { const k = ent.pid + '|' + ent.tid; touched.add(k); if (ent.rec) dR[k] = (dR[k] || 0) + 1; else dP[k] = (dP[k] || 0) + 1; }
    }
    if (ch) await Store.setAgenda(id, doc);
  }
  for (const k of touched) { const [pid, tid] = k.split('|'); await adjustPlan(pid, tid, -(dP[k] || 0), -(dR[k] || 0), finalize); }
  return n;
}

/* ================= perfiles y horarios ================= */
function schedSummary(u) {
  if (!isPro(u)) return isAdminU(u) ? 'Accede a las agendas de todos los profesionales' : 'Publica noticias para el equipo';
  const parts = ORDER.filter(d => S.cfg.days.includes(d) && u.schedule && u.schedule[d] && u.schedule[d].on)
    .map(d => `${DAYS_S[d]} ${u.schedule[d].from}–${u.schedule[d].to} h`);
  return parts.length ? parts.join(', ') : 'Sin horarios cargados';
}

function schedHTML(sched) {
  const days = ORDER.filter(d => S.cfg.days.includes(d));
  return `<div class="lbl" style="margin-bottom:2px">Horario de trabajo</div>
    <p class="hint">Tildá los días que atiende y elegí desde y hasta qué hora. Solo en esas franjas se pueden cargar pacientes.</p>
    ${days.map(d => { const s = sched[d] || {}; const on = !!s.on;
      const from = s.from != null ? s.from : S.cfg.open, to = s.to != null ? s.to : S.cfg.close;
      return `<div class="srow ${on ? '' : 'off'}" data-d="${d}">
        <label class="chk"><input type="checkbox" name="on${d}" ${on ? 'checked' : ''}><span>${DAYS[d]}</span></label>
        <select name="from${d}" aria-label="Desde ${DAYS[d]}" ${on ? '' : 'disabled'}>${hourOpts(S.cfg.open, S.cfg.close - 1, from)}</select>
        <span class="a">a</span>
        <select name="to${d}" aria-label="Hasta ${DAYS[d]}" ${on ? '' : 'disabled'}>${hourOpts(S.cfg.open + 1, S.cfg.close, to)}</select></div>`; }).join('')}
    <div class="actions" style="margin-bottom:14px"><button type="button" class="btn ghost small" data-copyfirst>Copiar el primer día tildado a todos</button></div>`;
}

function readSchedule(form) {
  const s = {};
  S.cfg.days.forEach(d => {
    const on = form.elements['on' + d].checked;
    const from = +form.elements['from' + d].value, to = +form.elements['to' + d].value;
    if (on && to <= from) throw new Error(`${DAYS[d]}: la hora de fin debe ser posterior a la de inicio.`);
    s[d] = { on, from, to };
  });
  return s;
}

function userFormHTML(u, isNew, canRole) {
  const profs = profilesOf(u).length ? profilesOf(u) : ['kinesiologo'];
  return `<form id="uf" autocomplete="off">
    <label class="fld"><span>Nombre y apellido</span><input type="text" name="name" required maxlength="80" value="${esc(u.name || '')}"></label>
    <div class="fld"><span>Foto de perfil</span><div class="phrow"><span id="phprev">${avatarHTML(u, 64)}</span><div><button type="button" class="btn ghost small" data-pickphoto>Elegir foto</button><button type="button" class="btn ghost small" data-rmphoto>Quitar</button></div></div></div>
    <label class="fld"><span>Título y matrícula <small>(opcional)</small></span><input type="text" name="title" maxlength="100" placeholder="Lic. en Kinesiología, M.P. 1234" value="${esc(u.title || '')}"></label>
    ${canRole ? `<div class="fld"><span>Perfiles <small>(uno o más)</small></span><div class="rchips">${PROFILE_OPTS.map(([v, l, d]) => `<label class="chip" title="${esc(d)}"><input type="checkbox" name="pf" value="${v}" ${profs.includes(v) ? 'checked' : ''}><span>${esc(l)}</span></label>`).join('')}</div></div>` : `<p class="hint">Perfil: <b>${esc(roleText(u))}</b></p>`}
    <div class="fld" id="rolesBox" ${profs.includes('kinesiologo') ? '' : 'hidden'}><span>Especialidades de kinesiología <small>(una o más)</small></span>
      <div class="rchips">${[...new Set([...(S.cfg.roles || []), ...(u.roles || [])])].map(r => `<label class="chip"><input type="checkbox" name="r" value="${esc(r)}" ${(u.roles || []).includes(r) ? 'checked' : ''}><span>${esc(r)}</span></label>`).join('')}</div></div>
    <label class="fld"><span>DNI <small>(con este dato ingresa a la agenda)</small></span><input type="text" name="dni" inputmode="numeric" maxlength="15" required value="${esc(u.dni || '')}"></label>
    <div id="schedBox" ${isPro({ profiles: profs }) ? '' : 'hidden'}>${schedHTML(u.schedule || {})}</div>
    <p class="err" id="ferr"></p>
    <div class="actions" id="uactions"></div>
  </form>`;
}

function bindUserForm(id, isNew, opts) {
  const f = $('#uf'); const u = S.users[id] || {};
  const formProfiles = () => { const boxes = [...f.querySelectorAll('input[name=pf]')]; return boxes.length ? boxes.filter(x => x.checked).map(x => x.value) : profilesOf(u); };
  const acts = $('#uactions');
  let photoState = (u && u.photo) || '';
  acts.innerHTML = `<button class="btn" type="submit">Guardar</button>${opts.onCancel ? '<button class="btn ghost" type="button" data-cancel>Cancelar</button>' : ''}${opts.canDelete ? '<button class="btn danger" type="button" data-remove>Eliminar perfil</button>' : ''}`;
  const syncRow = row => { const on = row.querySelector('input[type=checkbox]').checked; row.classList.toggle('off', !on); row.querySelectorAll('select').forEach(s => s.disabled = !on); };
  f.addEventListener('change', e => {
    if (e.target.name === 'pf') { const pf = formProfiles(); $('#schedBox').hidden = !isPro({ profiles: pf }); $('#rolesBox').hidden = !pf.includes('kinesiologo'); }
    const row = e.target.closest('.srow'); if (row && e.target.type === 'checkbox') syncRow(row);
  });
  f.addEventListener('click', async e => {
    if (e.target.closest('[data-copyfirst]')) {
      const rows = [...f.querySelectorAll('.srow')]; const src = rows.find(r => r.querySelector('input[type=checkbox]').checked);
      if (!src) return toast('Tildá primero un día.');
      const fr = src.querySelector('select[name^=from]').value, to = src.querySelector('select[name^=to]').value;
      rows.forEach(r => { r.querySelector('input[type=checkbox]').checked = true; r.querySelector('select[name^=from]').value = fr; r.querySelector('select[name^=to]').value = to; syncRow(r); });
    }
    if (e.target.closest('[data-pickphoto]')) choosePhoto(ph => { photoState = ph; $('#phprev').innerHTML = avatarHTML({ photo: ph }, 64); });
    if (e.target.closest('[data-rmphoto]')) { photoState = ''; $('#phprev').innerHTML = avatarHTML({}, 64); }
    if (e.target.closest('[data-cancel]')) opts.onCancel();
    if (e.target.closest('[data-remove]')) {
      if (!(await confirmBox(`Se elimina el perfil de ${u.name}. Sus turnos ya cargados quedan guardados.`, 'Eliminar'))) return;
      try { await Store.delUser(id); toast('Perfil eliminado'); opts.onDone && opts.onDone(); } catch (er) { toast('No se pudo eliminar.'); }
    }
  });
  f.onsubmit = async e => {
    e.preventDefault();
    const err = $('#ferr'); err.textContent = '';
    if (!(isSec() || id === S.me)) { err.textContent = 'No tenés permiso para editar este perfil.'; return; }
    const dni = normDni(f.dni.value);
    if (!DNI_OK.test(dni)) { err.textContent = 'Revisá el DNI: tiene que tener entre 6 y 12 números.'; return; }
    if (dniTaken(dni, id)) { err.textContent = 'Ese DNI ya está cargado en otro perfil.'; return; }
    const profiles = formProfiles();
    if (!profiles.length) { err.textContent = 'Elegí al menos un perfil.'; return; }
    if (!isSec() && profiles.join() !== profilesOf(u).join()) { err.textContent = 'No podés cambiar tu perfil.'; return; }
    let schedule = u.schedule || {};
    try { if (isPro({ profiles })) schedule = readSchedule(f); } catch (er) { err.textContent = er.message; return; }
    const roles = profiles.includes('kinesiologo') ? [...f.querySelectorAll('input[name=r]:checked')].map(x => x.value) : [];
    const data = { name: f.name.value.trim(), title: f.title.value.trim(), role: mainRole(profiles), profiles, roles, schedule, photo: photoState, dni };
    try { await Store.setUser(id, data); toast(isNew ? 'Perfil creado' : 'Cambios guardados'); opts.onDone && opts.onDone(); }
    catch (er) { err.textContent = (er && er.status === 403 && er.message) || 'No se pudo guardar. Revisá tu permiso de edición sobre esta página.'; }
  };
}

function viewTeam() {
  const list = Object.entries(S.users).sort((a, b) => (isAdminU(a[1]) === isAdminU(b[1]) ? byName(a, b) : isAdminU(a[1]) ? -1 : 1));
  $('#view').innerHTML = `<section class="panel">
    <div class="head-row"><h2>Equipo</h2><button class="btn" id="addu">Agregar integrante</button></div>
    <p class="hint">Cada profesional entra con su DNI y trabaja con su propia agenda, sus horarios y sus pacientes: no ve ni modifica lo de los demás. Administración y secretaría ven y editan todo. Una persona puede tener más de un perfil.</p>
    ${list.map(([id, u]) => `<div class="person"><div style="display:flex;gap:12px;align-items:center">${avatarHTML(u, 46)}<div><h3>${esc(u.name)}${profilesOf(u).map(r => `<span class="badge ${ADMIN_ROLES.includes(r) ? 'sec' : r === 'medico' ? 'med' : ''}">${esc(ROLE_LABEL[r] || r)}</span>`).join('')}</h3>
      ${u.title ? `<p>${esc(u.title)}</p>` : ''}${(u.roles || []).length ? `<p>Especialidades: ${esc(u.roles.join(', '))}</p>` : ''}<p>${esc(schedSummary(u))}</p></div></div>
      <button class="btn ghost small" data-edit="${id}">Editar</button></div>`).join('')}
  </section>`;
  $('#addu').onclick = () => editUserModal(null);
  $('#view').onclick = e => { const b = e.target.closest('[data-edit]'); if (b) editUserModal(b.dataset.edit); };
}

function editUserModal(id) {
  const isNew = !id; const nid = id || 'u' + uid();
  const u = isNew ? { role: 'kinesiologo', profiles: ['kinesiologo'], roles: [], schedule: defaultSchedule() } : S.users[nid];
  openModal(`<button class="btn ghost small close" data-close>Cerrar</button><h2>${isNew ? 'Nuevo integrante' : 'Editar perfil'}</h2><p class="sub">${isNew ? 'Completá los datos, los roles y el horario de trabajo.' : esc(u.name)}</p>
    ${userFormHTML(u, isNew, nid !== S.me)}`);
  $('#modal').onclick = e => { if (e.target.matches('[data-scrim]') || e.target.closest('[data-close]')) closeModal(); };
  bindUserForm(nid, isNew, { canDelete: !isNew && nid !== S.me, onCancel: closeModal, onDone: closeModal });
}
function defaultSchedule() { const s = {}; S.cfg.days.forEach(d => s[d] = { on: true, from: S.cfg.open, to: S.cfg.close }); return s; }

function viewProfile() {
  const u = S.users[S.me];
  $('#view').innerHTML = `<section class="panel"><h2>Mi perfil</h2>
    <p class="hint">Definí tus días y horas de trabajo. En esas franjas se te pueden asignar pacientes; el resto queda cerrado en tu agenda.</p>
    ${userFormHTML(u, false, false)}</section>`;
  bindUserForm(S.me, false, { onDone: () => { S.sig = ''; render(); renderView(true); } });
}

/* ================= configuración ================= */
function viewConfig() {
  const c = S.cfg;
  $('#view').innerHTML = `<section class="panel"><h2>Configuración del centro</h2>
    <p class="hint">Estos valores valen para toda la agenda. Solo la secretaría puede cambiarlos.</p>
    <form id="cf" autocomplete="off">
      <div class="fld"><span>Días de atención</span>
        <div class="chips">${ORDER.map(d => `<label class="chip"><input type="checkbox" name="d" value="${d}" ${c.days.includes(d) ? 'checked' : ''}><span>${DAYS_S[d]}</span></label>`).join('')}</div>
        <small>Solo estos días aparecen en la agenda semanal.</small></div>
      <div class="fld"><span>Horario del centro</span>
        <div style="display:flex;gap:10px;align-items:center"><select name="open" aria-label="Apertura">${hourOpts(0, 22, c.open)}</select><span>a</span><select name="close" aria-label="Cierre">${hourOpts(1, 23, c.close)}</select></div></div>
      <label class="fld"><span>Pacientes por hora <small>(por kinesiólogo)</small></span><input type="number" name="cap" min="1" max="20" value="${c.cap}" style="max-width:120px"></label>
      <div class="fld"><span>Valor por sesión según categoría de pago <small>(opcional: completa solo el monto facturado)</small></span>
        <div class="row4">${[1, 2, 3, 4].map(k => `<label class="fld" style="margin:0"><span style="font-weight:500">Categoría ${k}</span><input type="text" name="cp${k}" inputmode="decimal" placeholder="$ 0" value="${esc(numFmt((c.catPrices || {})[k] || null))}"></label>`).join('')}</div></div>
      <label class="fld"><span>Duración de la consulta médica</span><select name="medMin" style="max-width:160px">${[10, 15, 20, 30].map(v => `<option value="${v}"${v === c.medMin ? ' selected' : ''}>${v} minutos</option>`).join('')}</select></label>
      <label class="fld"><span>Sobreturnos máximos por consulta <small>(los asigna el médico)</small></span><input type="number" name="sobre" min="0" max="5" value="${c.sobre}" style="max-width:120px"></label>
      <label class="fld"><span>Recuperos máximos por tratamiento <small>(sesiones que se pueden reprogramar)</small></span><input type="number" name="maxRec" min="0" max="10" value="${c.maxRec}" style="max-width:120px"></label>
      <label class="fld"><span>Aviso de fin de tratamiento <small>(cuántas sesiones programadas le quedan al paciente)</small></span><input type="number" name="endReminder" min="1" max="10" value="${c.endReminder}" style="max-width:120px"></label>
      <label class="fld"><span>Roles de kinesiología <small>(uno por línea)</small></span><textarea name="roles" rows="8">${esc((c.roles || []).join('\n'))}</textarea></label>
      <p class="err" id="ferr"></p>
      <button class="btn" type="submit">Guardar configuración</button>
    </form></section>
    <section class="panel" id="hol" style="margin-top:14px"></section>
    <section class="panel" id="bkp" style="margin-top:14px"><p class="hint">Cargando copias…</p></section>`;
  renderHolidays();
  renderBackups();
  $('#cf').onsubmit = async e => {
    e.preventDefault(); const f = e.target; const err = $('#ferr'); err.textContent = '';
    if (!isSec()) { err.textContent = 'No tenés permiso.'; return; }
    const days = [...f.querySelectorAll('input[name=d]:checked')].map(x => +x.value);
    const open = +f.open.value, close = +f.close.value, cap = Math.max(1, Math.min(20, parseInt(f.cap.value, 10) || 8));
    if (!days.length) { err.textContent = 'Elegí al menos un día de atención.'; return; }
    if (close <= open) { err.textContent = 'El cierre debe ser posterior a la apertura.'; return; }
    const roles = [...new Set(f.roles.value.split('\n').map(x => x.trim().slice(0, 40)).filter(Boolean))].slice(0, 40);
    const medMin = +f.medMin.value, sobre = Math.max(0, Math.min(5, parseInt(f.sobre.value, 10) || 0));
    const maxRec = Math.max(0, Math.min(10, parseInt(f.maxRec.value, 10) || 0));
    const endReminder = Math.max(1, Math.min(10, parseInt(f.endReminder.value, 10) || 2));
    const catPrices = {}; [1, 2, 3, 4].forEach(k => { const v = parseMoney(f['cp' + k].value); if (v > 0) catPrices[k] = v; });
    try { await Store.setCfg(Object.assign({}, S.cfg, { days, open, close, cap, medMin, sobre, maxRec, roles, catPrices, endReminder })); toast('Configuración guardada'); S.sig = ''; setTimeout(() => { render(); renderView(true); }, 50); }
    catch (er) { err.textContent = 'No se pudo guardar. Revisá tu permiso de edición.'; }
  };
}

